<template>
  <view class="container">
    <button @tap="chooseImage">选择/拍摄照片</button>
    <image v-if="imgSrc" :src="imgSrc" mode="aspectFit" style="width: 300px; height: 300px;" />
    
    <view v-if="advice" class="result">
      <text>AI 建议：</text>
      <text>{{ advice }}</text>
    </view>

    <button v-if="audioUrl" @tap="playAudio">🔊 播放建议</button>
  </view>
</template>

<script>
import { uploadImageToServer } from '@/utils/request.js'

export default {
  data() {
    return {
      imgSrc: '',
      advice: '',
      audioUrl: '',
      innerAudioContext: null
    }
  },
  methods: {
    chooseImage() {
      uni.chooseImage({
        count: 1,
        sourceType: ['camera', 'album'],
        success: (res) => {
          const path = res.tempFilePaths[0]
          this.imgSrc = path
          this.advice = '正在分析，请稍候...'
          this.audioUrl = ''

          uploadImageToServer(path).then(res => {
            if (res && res.advice) {
              this.advice = res.advice
              this.audioUrl = res.audioUrl
              this.playAudio() // 自动播放一次
            } else if (res && res.error) {
              this.advice = '服务器错误：' + res.error
            } else {
              this.advice = '未获取到有效建议'
            }
          }).catch(err => {
            console.error(err)
            this.advice = '分析失败，请稍后重试'
          })
        }
      })
    },
    playAudio() {
      if (!this.audioUrl) return
      if (!this.innerAudioContext) {
        this.innerAudioContext = uni.createInnerAudioContext()
      }
      this.innerAudioContext.src = this.audioUrl
      this.innerAudioContext.play()

      this.innerAudioContext.onError((res) => {
        console.error('音频播放错误：', res)
        uni.showToast({ title: '语音播放失败', icon: 'none' })
      })
    }
  },
  onUnload() {
    if (this.innerAudioContext) {
      this.innerAudioContext.destroy()
    }
  }
}
</script>

<style>
.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 40px;
}
.result {
  margin-top: 20px;
  font-size: 16px;
  color: #333;
  text-align: center;
}
</style>
